(function ($) {
    "use strict";
    Gordic.Previews.register("ppp:DokumentySymPreview", {
        canRender: (dto) => dto.ixb != null, // není - li ixb nemá smysl něco zobrazovat                
        render: (div, dto) => {
            const currentElement = $(div);
            currentElement.empty().append("<h2 class='g-state-text g-state-active' style='margin: 0.5rem;'>" + dto.popis + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/>");
            const frm = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1, L-4-8-0, M-4-8-0, breaks-300-400" })
                .addSection()
                .addRow("jres:27360260").addField("gdatebox", { valueType: "datetime", name: "dat_zmena", disabled: true }) //RC 27360260 : Datum a čas
                .addRow("jres:27360261").addField("gstringbox", { name: "nazev_rf", disabled: true }) //RC 27360261 : Uložil
            ;
            const input = {
                specifikace: "dokumenty_sym",
                ixb: dto.ixb,
                ixs: dto.ixs,
                soubor_pri: dto.soubor_pri
            };
            const previewData = { gcontent: "Gordic.Pam.Server.GFilePreview", method: "RunAsync", input: input };
            $("<div>").appendTo(currentElement).gform("createFrom", frm).findFields().gfield("model", "apply", dto);
            $("<div>").appendTo(currentElement)
                .gfilepreview({})
                .gfilepreview("displayFromServer", previewData);
        }
    });
})(jQuery);
