                /**
                * Načtení přehledu - async
                * @param cnt content
                * @param panel panel
                */
                async nactiPrehledAsync(cnt, panel) {
                    const Content = cnt;
                    const panel_kod = Gordic.Pam.toString(panel.panel_kod);
                    // nastaveni prehledu
                    const dto = {
                        panel_kod: panel_kod,
                        panel_txt: Gordic.Pam.toString(panel.panel_txt),
                        kategorie_ppp_txt: Gordic.Pam.toString(panel.kategorie_ppp_txt),
                        zamestnanec: 0,
                        pocet_dni_po: panel.pocet_dni_po,
                        pocet_dni_pred: panel.pocet_dni_pred
                    };
                    const guid = Gordic.Pam.CreateGuid();
                    Content.beginOperation({ id: guid, text: `${panel.panel_txt} (${panel.panel_kod})` });
                    try {
                        // ziskani nastaveni panelu
                        const setting = await Content.isl.PersCenterPrehled
                            .panelSetting({ panel_kod, zamestnanec: 0 })
                            .get();
                        // ziskani dat
                        const data = await Gordic.Pam.Isl(Content, Gordic.Pam.toString(setting.isl_class), Gordic.Pam.toString(setting.isl_method), dto);
                        // doplneni dat
                        if (Array.isArray(data["data"])) {
                            let row_number = 1;
                            data["data"].forEach((row) => {
                                row.panel_kod = setting.panel_kod;
                                row.poradi = setting.poradi;
                                row.poradi2 = row_number++;
                            });
                        }
                        // vratit data
                        return data["data"];
                    }
                    catch (error) {
                        console.error("Chyba při načítání přehledu: " + panel_kod, error);
                        throw error;
                    }
                    finally {
                        Content.endOperation(guid);
                    }
                }
