                        { coltype: Gordic.Pam.PamColumnType.int, colTemplate: { name: "poradi", caption: "Pořadí", hidden: true, sysColumn: true } },
                        { coltype: Gordic.Pam.PamColumnType.int, colTemplate: { name: "poradi2", caption: "Pořadí v panelu", hidden: true, sysColumn: true } }
