                                obec_kod: IsCZ ?
                                    Gordic.Pam.TryGetValueDef(form.findFormSections(cSectName_Adresa).findFields("obec" + suffix).gfield("getValue"), "obec_kod") :
                                    null,
                                obec: IsCZ ?
                                    Gordic.Pam.TryGetValueDef(form.findFormSections(cSectName_Adresa).findFields("obec" + suffix).gfield("getValue"), "obec_nazev") :
                                    form.findFormSections(cSectName_Adresa).findFields("obec" + suffix).gfield("getValue"),
                                cast_obce_kod: IsCZ ?
                                    Gordic.Pam.TryGetValueDef(form.findFormSections(cSectName_Adresa).findFields("cast_obce" + suffix).gfield("getValue"), "cast_obce_kod") :
                                    null,
