                                ulice_kod: IsCZ ?
                                    Gordic.Pam.TryGetValueDef(form.findFormSections(cSectName_Adresa).findFields("ulice" + suffix).gfield("getValue"), "ulice_kod") :
                                    null,
                                ulice: IsCZ ?
                                    Gordic.Pam.TryGetValueDef(form.findFormSections(cSectName_Adresa).findFields("ulice" + suffix).gfield("getValue"), "ulice_nazev") :
                                    form.findFormSections(cSectName_Adresa).findFields("ulice" + suffix).gfield("getValue"),
                                cpop: IsCZ ?
                                    Gordic.Pam.TryGetValueDef(form.findFormSections(cSectName_Adresa).findFields("cpop" + suffix).gfield("getValue"), "cpop_nazev") :
                                    form.findFormSections(cSectName_Adresa).findFields("cpop" + suffix).gfield("getValue"),
