                /**
                 * Automatický výpočet součtu/rozdílu mezi dvěma poli a aktualizace cílového pole
                 * @param field_name Název změněného pole
                 * @param row Řádek dat
                 * @param view Pohled pro aktualizaci dat
                 * @param sourceField1 První zdrojové pole
                 * @param sourceField2 Druhé zdrojové pole
                 * @param targetField Cílové pole pro výsledek
                 */
                autoSum(field_name, row, view, sourceField1, sourceField2, targetField) {
                    // Kontrola, zda bylo změněno jedno ze zdrojových polí a obě pole mají hodnotu
                    if ([sourceField1, sourceField2].includes(field_name) && row?.[sourceField1] != null && row?.[sourceField2] != null) {
                        // Výpočet časového rozdílu a aktualizace dat
                        const rozdilTxt = Gordic.Pam.timeStrDiff(row[sourceField1], row[sourceField2]);
                        const rozdil = Gordic.Pam.Str2PocHodin(rozdilTxt, "hh:mm");
                        const jePracovniCas = (sourceField1 === 'pole_2' && sourceField2 === 'pole_3' && targetField === 'pole_4' && rozdil > 0.5);
                        row[targetField] = jePracovniCas ? Gordic.Pam.timeStrDiff(rozdilTxt, "00:30") : rozdilTxt; // odečte přestávku
                        view.updateDataRaw(row);
                    }
                }
